inference_trace:
Process the hits in reverse with a union-find:

1. **Remove all hit bricks first.** Copy the grid, then set every hit cell to 0. A hit on an empty cell is marked with a value like -1, which stays nonzero but is treated as empty for connectivity, so it can be skipped later.
2. **Add a virtual top node** `T = m*n`. Every brick in row 0 is unioned with `T`.
3. **Build the final state.** Union all adjacent remaining bricks.
4. **Add hits back in reverse order.** For each hit that originally held a brick:
   - Record `before = size(T)`.
   - Restore the brick. If it is in row 0, union it with `T`. Union it with each neighbour that is a brick.
   - Record `after = size(T)`.
   - The answer for this hit is `max(0, after - before - 1)`. The `-1` excludes the restored brick itself; the `max` covers the case where it did not connect to the top.
5. Hits on empty cells give 0.

The union-find uses path compression (iterative) and union by size.

```javascript
/**
 * @param {number[][]} grid
 * @param {number[][]} hits
 * @return {number[]}
 */
var hitBricks = function(grid, hits) {
    const m = grid.length, n = grid[0].length;
    const T = m * n;
    const parent = new Int32Array(T + 1);
    const size = new Int32Array(T + 1);
    for (let i = 0; i <= T; i++) { parent[i] = i; size[i] = 1; }
    const find = (x) => {
        let r = x;
        while (parent[r] !== r) r = parent[r];
        while (parent[x] !== r) { const nx = parent[x]; parent[x] = r; x = nx; }
        return r;
    };
    const union = (a, b) => {
        a = find(a); b = find(b);
        if (a === b) return;
        if (size[a] < size[b]) { const t = a; a = b; b = t; }
        parent[b] = a;
        size[a] += size[b];
    };
    const g = grid.map(r => r.slice());
    const had = new Array(hits.length);
    for (let i = 0; i < hits.length; i++) {
        const [r, c] = hits[i];
        had[i] = g[r][c] === 1;
        g[r][c] = 0;
    }
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (g[r][c] !== 1) continue;
            const id = r * n + c;
            if (r === 0) union(id, T);
            if (r > 0 && g[r - 1][c] === 1) union(id, id - n);
            if (c > 0 && g[r][c - 1] === 1) union(id, id - 1);
        }
    }
    const dr = [1, -1, 0, 0], dc = [0, 0, 1, -1];
    const res = new Array(hits.length).fill(0);
    for (let i = hits.length - 1; i >= 0; i--) {
        if (!had[i]) continue;
        const [r, c] = hits[i];
        const before = size[find(T)];
        const id = r * n + c;
        g[r][c] = 1;
        if (r === 0) union(id, T);
        for (let d = 0; d < 4; d++) {
            const nr = r + dr[d], nc = c + dc[d];
            if (nr < 0 || nc < 0 || nr >= m || nc >= n) continue;
            if (g[nr][nc] === 1) union(id, nr * n + nc);
        }
        const after = size[find(T)];
        res[i] = Math.max(0, after - before - 1);
    }
    return res;
};
```

