    const M = 1000000007;
    let a = 1, e = 1, i = 1, o = 1, u = 1;
    for (let k = 1; k < n; k++) {
        const na = (e + i + u) % M;
        const ne = (a + i) % M;
        const ni = (e + o) % M;
        const no = i % M;
        const nu = (i + o) % M;
        a = na; e = ne; i = ni; o = no; u = nu;
    }
    return (a + e + i + o + u) % M;
};
