Walk through the array once and keep the last index we have already added to the result.

1. For each `j` where `nums[j] == key`, the k-distant indices it covers are the range `[j - k, j + k]`, clipped to the array bounds.
2. Start that range at `max(j - k, last + 1)`. This skips anything already added, so there are no duplicates and the output stays sorted.
3. Add every index up to `min(n - 1, j + k)` and update `last` as we go.

Each index is added at most once, so the total time is O(n).

```javascript
/**
 * @param {number[]} nums
 * @param {number} key
 * @param {number} k
 * @return {number[]}
 */
var findKDistantIndices = function(nums, key, k) {
    const n = nums.length;
    const res = [];
    let last = -1;
    for (let j = 0; j < n; j++) {
        if (nums[j] === key) {
            const start = Math.max(j - k, last + 1);
            const end = Math.min(n - 1, j + k);
            for (let i = start; i <= end; i++) {
                res.push(i);
                last = i;
            }
        }
    }
    return res;
};
