Use reverse topological sort (Kahn's algorithm on the reversed graph):

1. A terminal node has outdegree 0, so it is safe.
2. Build the reversed graph and record each node's outdegree.
3. Start a queue with every node whose outdegree is 0.
4. Pop a node; for each predecessor in the reversed graph, decrement its outdegree. When a predecessor's outdegree reaches 0, all of its edges lead to safe nodes, so it is safe too and joins the queue.
5. Nodes still left with outdegree > 0 at the end can reach a cycle and are unsafe.
6. Scanning node indices in order gives the safe nodes already sorted ascending.

```javascript
/**
 * @param {number[][]} graph
 * @return {number[]}
 */
var eventualSafeNodes = function(graph) {
    const n = graph.length;
    const outdeg = new Int32Array(n);
    const rev = Array.from({length: n}, () => []);
    for (let i = 0; i < n; i++) {
        outdeg[i] = graph[i].length;
        for (const j of graph[i]) rev[j].push(i);
    }
    const queue = [];
    for (let i = 0; i < n; i++) if (outdeg[i] === 0) queue.push(i);
    const safe = new Uint8Array(n);
    let head = 0;
    while (head < queue.length) {
        const u = queue[head++];
        safe[u] = 1;
        for (const p of rev[u]) {
            if (--outdeg[p] === 0) queue.push(p);
        }
    }
    const res = [];
    for (let i = 0; i < n; i++) if (safe[i]) res.push(i);
    return res;
};
```

