Approach:

- Keep the last `m` stream elements in a circular buffer.
- Maintain two Fenwick trees indexed by value (1..100000): one counts elements, the other sums their values. Each add or evict updates both trees.
- Define `sumFirst(t)` as the sum of the `t` smallest elements in the window. Binary lifting on the count tree finds the largest value `pos` whose prefix count is still below `t`, collecting count and sum along the way. The remaining `t - cnt` elements all equal `pos + 1`.
- The MKAverage is `(sumFirst(m - k) - sumFirst(k)) / (m - 2k)`, rounded down.
- Sums reach at most about 1e10, which JavaScript numbers hold exactly.
- Each operation costs O(log V), where V = 100000.

```javascript
/**
 * @param {number} m
 * @param {number} k
 */
var MKAverage = function(m, k) {
    this.m = m;
    this.k = k;
    this.N = 100001;
    this.cnt = new Float64Array(this.N + 1);
    this.sum = new Float64Array(this.N + 1);
    this.buf = new Int32Array(m);
    this.size = 0;
    this.pos = 0;
    this.LOG = 1;
    while ((this.LOG << 1) <= this.N) this.LOG <<= 1;
};

MKAverage.prototype._upd = function(v, c) {
    for (let i = v; i <= this.N; i += i & (-i)) {
        this.cnt[i] += c;
        this.sum[i] += c * v;
    }
};

MKAverage.prototype._sumFirst = function(t) {
    let pos = 0, c = 0, s = 0;
    for (let step = this.LOG; step > 0; step >>= 1) {
        const np = pos + step;
        if (np <= this.N && c + this.cnt[np] < t) {
            pos = np;
            c += this.cnt[np];
            s += this.sum[np];
        }
    }
    return s + (t - c) * (pos + 1);
};

/** 
 * @param {number} num
 * @return {void}
 */
MKAverage.prototype.addElement = function(num) {
    if (this.size === this.m) {
        const old = this.buf[this.pos];
        this._upd(old, -1);
    } else {
        this.size++;
    }
    this.buf[this.pos] = num;
    this.pos = (this.pos + 1) % this.m;
    this._upd(num, 1);
};

/**
 * @return {number}
 */
MKAverage.prototype.calculateMKAverage = function() {
    if (this.size < this.m) return -1;
    const a = this._sumFirst(this.m - this.k);
    const b = this._sumFirst(this.k);
    return Math.floor((a - b) / (this.m - 2 * this.k));
};
```

