Put every value of `nums` into a set. Then walk the linked list once.

A component ends at a node whose value is in the set when either:
- the next node does not exist, or
- the next node's value is not in the set.

So the answer is the number of nodes that satisfy this "end of component" condition. This runs in O(n) time with O(|nums|) extra space.

```javascript
/**
 * Definition for singly-linked list.
 * function ListNode(val, next) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.next = (next===undefined ? null : next)
 * }
 */
/**
 * @param {ListNode} head
 * @param {number[]} nums
 * @return {number}
 */
var numComponents = function(head, nums) {
    const set = new Set(nums);
    let count = 0;
    let cur = head;
    while (cur) {
        if (set.has(cur.val) && (!cur.next || !set.has(cur.next.val))) {
            count++;
        }
        cur = cur.next;
    }
    return count;
};
```

