Sort the words by length so every predecessor is processed before the words built from it.

For each word, try deleting each of its characters one at a time. If the shortened string is already in the map, it is a predecessor, so the chain ending at this word can be one longer than the chain ending there. Store the best chain length for the word in the map and keep a running maximum.

Duplicate words are harmless: both copies get the same value, so the answer is unaffected.

Complexity is O(n · L²) with L ≤ 16, which is easily fast enough for n ≤ 1000.

```javascript
/**
 * @param {string[]} words
 * @return {number}
 */
var longestStrChain = function(words) {
    const sorted = [...words].sort((a, b) => a.length - b.length);
    const dp = new Map();
    let best = 0;
    for (const w of sorted) {
        let cur = 1;
        for (let i = 0; i < w.length; i++) {
            const p = w.slice(0, i) + w.slice(i + 1);
            if (dp.has(p)) cur = Math.max(cur, dp.get(p) + 1);
        }
        dp.set(w, Math.max(dp.get(w) || 0, cur));
        best = Math.max(best, cur);
    }
    return best;
};
```

