inference_trace:
Precompute the compatibility score for every student-mentor pair. Then run a bitmask DP over the set of mentors already used.

- `dp[mask]` is the best total score when the first `popcount(mask)` students have been assigned to exactly the mentors in `mask`.
- From each reachable `mask`, the next student is `i = popcount(mask)`.
- Try giving student `i` every unused mentor `j`, and update `dp[mask | (1 << j)]` with `dp[mask] + score[i][j]`.
- The answer is `dp[(1 << m) - 1]`.

With `m <= 8`, there are at most 256 masks, so this runs in O(2^m · m) after the O(m²·n) score precomputation.

```javascript
/**
 * @param {number[][]} students
 * @param {number[][]} mentors
 * @return {number}
 */
var maxCompatibilitySum = function(students, mentors) {
    const m = students.length, n = students[0].length;
    const score = [];
    for (let i = 0; i < m; i++) {
        score.push([]);
        for (let j = 0; j < m; j++) {
            let s = 0;
            for (let k = 0; k < n; k++) if (students[i][k] === mentors[j][k]) s++;
            score[i].push(s);
        }
    }
    const full = 1 << m;
    const dp = new Array(full).fill(-1);
    dp[0] = 0;
    for (let mask = 0; mask < full; mask++) {
        if (dp[mask] < 0) continue;
        let i = 0, x = mask;
        while (x) { i += x & 1; x >>= 1; }
        if (i >= m) continue;
        for (let j = 0; j < m; j++) {
            if (mask & (1 << j)) continue;
            const nm = mask | (1 << j);
            dp[nm] = Math.max(dp[nm], dp[mask] + score[i][j]);
        }
    }
    return dp[full - 1];
};
```

