var minCost = function(maxTime, edges, passingFees) {
    const n = passingFees.length;
    const T = maxTime + 1;
    const dp = new Float64Array(T * n).fill(Infinity);
    dp[0] = passingFees[0];
    for (let t = 0; t <= maxTime; t++) {
        const base = t * n;
        for (const [u, v, w] of edges) {
            const nt = t + w;
            if (nt > maxTime) continue;
            const nb = nt * n;
            const du = dp[base + u];
            if (du !== Infinity) {
                const c = du + passingFees[v];
                if (c < dp[nb + v]) dp[nb + v] = c;
