 * @param {number[][]} grid
 * @return {number}
 */
var minDays = function(grid) {
    const m = grid.length, n = grid[0].length;
    const count = () => {
        const seen = new Uint8Array(m * n);
        let c = 0;
        const stack = [];
        for (let i = 0; i < m; i++) {
            for (let j = 0; j < n; j++) {
                if (grid[i][j] === 1 && !seen[i * n + j]) {
                    c++;
                    if (c > 1) return c;
                    seen[i * n + j] = 1;
                    stack.push(i * n + j);
