 * @param {number[]} nums
 * @return {number}
 */
var minStartValue = function(nums) {
    let sum = 0, minPrefix = 0;
    for (const x of nums) {
        sum += x;
        if (sum < minPrefix) minPrefix = sum;
    }
    return 1 - minPrefix;
