Convert each date to a count of days since 1971-01-01, then return the absolute difference of the two counts.

For a date `YYYY-MM-DD`, the count is:
1. Add 365 days for each full year from 1971 up to `YYYY - 1`, plus 1 extra day for each leap year in that range.
2. Add the days in each full month before `MM`, using 29 for February when `YYYY` is a leap year.
3. Add `DD`.

A year is a leap year if it is divisible by 400, or divisible by 4 but not by 100.

```javascript
/**
 * @param {string} date1
 * @param {string} date2
 * @return {number}
 */
var daysBetweenDates = function(date1, date2) {
    const isLeap = y => (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
    const md = [31,28,31,30,31,30,31,31,30,31,30,31];
    const toDays = s => {
        const [y, m, d] = s.split('-').map(Number);
        let total = 0;
        for (let yr = 1971; yr < y; yr++) total += isLeap(yr) ? 366 : 365;
        for (let i = 0; i < m - 1; i++) {
            total += md[i];
            if (i === 1 && isLeap(y)) total += 1;
        }
        return total + d;
    };
    return Math.abs(toDays(date1) - toDays(date2));
};
```

