The problem reduces to a classic one: choose exactly n = len/3 slices, no two adjacent on the circle, so that their sum is maximal. Any such non-adjacent selection can be achieved by some order of picks.

To handle the circle, split it into two linear cases and take the better one:
- use slices[0..m-2] (exclude the last slice), or
- use slices[1..m-1] (exclude the first slice).

For each linear array `arr`, define `dp[i][j]` as the maximum sum using the first i elements with j of them picked and no two adjacent:

dp[i][j] = max(dp[i-1][j], dp[i-2][j-1] + arr[i-1])

States that cannot be reached are set to -Infinity, so that "exactly n" picks is enforced.

Complexity is O(m·n) time with m ≤ 500, which is fine.

```javascript
/**
 * @param {number[]} slices
 * @return {number}
 */
var maxSizeSlices = function(slices) {
    const m = slices.length;
    const n = m / 3;
    const solve = (arr) => {
        const L = arr.length;
        const NEG = -Infinity;
        const dp = [];
        for (let i = 0; i <= L; i++) {
            dp.push(new Array(n + 1).fill(NEG));
            dp[i][0] = 0;
        }
        for (let i = 1; i <= L; i++) {
            for (let j = 1; j <= n; j++) {
                let best = dp[i - 1][j];
                const prev = i >= 2 ? dp[i - 2][j - 1] : (j - 1 === 0 ? 0 : NEG);
                if (prev !== NEG) best = Math.max(best, prev + arr[i - 1]);
                dp[i][j] = best;
            }
        }
        return dp[L][n];
    };
    if (m === 3) return Math.max(...slices);
    return Math.max(solve(slices.slice(0, m - 1)), solve(slices.slice(1)));
};
```

