Use a union-find (disjoint set) structure over the people, and handle each request in order:

1. Find the roots `pu` and `pv` of `u` and `v`.
2. If `pu === pv`, they are already connected, so the request succeeds.
3. Otherwise, check every restriction `[x, y]`. Let `px` and `py` be their roots. If `{px, py}` equals `{pu, pv}`, merging the two groups would connect `x` and `y`, so the request fails.
4. If no restriction blocks it, union the two groups and mark the request successful.

Each request scans all restrictions, so the cost is about 1000 × 1000 = 10⁶ find operations. Path compression keeps each find fast enough for this limit.

```javascript
/**
 * @param {number} n
 * @param {number[][]} restrictions
 * @param {number[][]} requests
 * @return {boolean[]}
 */
var friendRequests = function(n, restrictions, requests) {
    const parent = new Int32Array(n);
    for (let i = 0; i < n; i++) parent[i] = i;
    const find = (x) => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };
    const res = [];
    for (const [u, v] of requests) {
        const pu = find(u), pv = find(v);
        if (pu === pv) { res.push(true); continue; }
        let ok = true;
        for (const [x, y] of restrictions) {
            const px = find(x), py = find(y);
            if ((px === pu && py === pv) || (px === pv && py === pu)) { ok = false; break; }
        }
        if (ok) parent[pu] = pv;
        res.push(ok);
    }
    return res;
};
```

