Precompute a map from each value to the list of indices where it appears. Each `pick` call then chooses one index from that list uniformly at random, which takes O(1) time.

```javascript
/**
 * @param {number[]} nums
 */
var Solution = function(nums) {
    this.map = new Map();
    for (let i = 0; i < nums.length; i++) {
        let arr = this.map.get(nums[i]);
        if (!arr) {
            arr = [];
            this.map.set(nums[i], arr);
        }
        arr.push(i);
    }
};

/** 
 * @param {number} target
 * @return {number}
 */
