Split each cell into 4 triangles: 0 = top, 1 = right, 2 = bottom, 3 = left. Union-find then joins triangles that share open space, and the answer is the number of distinct sets.

**Inside a cell:**
- `' '`: union all four triangles.
- `'/'`: the slash runs from bottom-left to top-right. It separates top+left from right+bottom, so union 0 with 3 and 1 with 2.
- `'\'`: the slash runs from top-left to bottom-right. It separates top+right from left+bottom, so union 0 with 1 and 2 with 3.

**Across cells:**
- The bottom triangle of cell (i, j) touches the top triangle of cell (i+1, j).
- The right triangle of cell (i, j) touches the left triangle of cell (i, j+1).

**Counting:** start with `4·n²` components and decrement each time a union actually merges two different sets.

```javascript
/**
 * @param {string[]} grid
 * @return {number}
 */
var regionsBySlashes = function(grid) {
    const n = grid.length;
    const N = 4 * n * n;
    const parent = new Int32Array(N);
    for (let i = 0; i < N; i++) parent[i] = i;
    let count = N;
    const find = (x) => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };
    const union = (a, b) => {
        a = find(a); b = find(b);
        if (a !== b) { parent[a] = b; count--; }
    };
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            const base = 4 * (i * n + j);
            const c = grid[i][j];
            if (c === ' ') {
                union(base, base + 1);
                union(base + 1, base + 2);
                union(base + 2, base + 3);
            } else if (c === '/') {
                union(base, base + 3);
                union(base + 1, base + 2);
            } else {
                union(base, base + 1);
                union(base + 2, base + 3);
            }
            if (i + 1 < n) union(base + 2, 4 * ((i + 1) * n + j));
            if (j + 1 < n) union(base + 1, 4 * (i * n + j + 1) + 3);
        }
    }
    return count;
};
```

