Use a bottom-up DP. Let `dp[len][i][j]` be true when `s1.substr(i, len)` can be scrambled into `s2.substr(j, len)`.

**Base case:** for `len = 1`, `dp[1][i][j]` is true exactly when `s1[i] == s2[j]`.

**Transition:** for longer lengths, try every split point `k` from 1 to `len - 1`:
- **No swap:** `dp[k][i][j] && dp[len-k][i+k][j+k]`.
- **Swap:** `dp[k][i][j+len-k] && dp[len-k][i+k][j]`.

If either holds for some `k`, then `dp[len][i][j]` is true.

**Indexing:** I use a flat array with index `(len*n + i)*n + j`, where `len` runs from 0 to `n`.

**Complexity:** there are O(n³) states and each takes O(n) work, so O(n⁴) total. With n ≤ 30 that is about 810k operations, which is fine.

```javascript
/**
 * @param {string} s1
 * @param {string} s2
 * @return {boolean}
 */
var isScramble = function(s1, s2) {
    const n = s1.length;
    if (n !== s2.length) return false;
    const dp = new Uint8Array((n + 1) * n * n);
    const idx = (l, i, j) => (l * n + i) * n + j;
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (s1[i] === s2[j]) dp[idx(1, i, j)] = 1;
        }
    }
    for (let len = 2; len <= n; len++) {
        for (let i = 0; i + len <= n; i++) {
            for (let j = 0; j + len <= n; j++) {
                for (let k = 1; k < len; k++) {
                    if ((dp[idx(k, i, j)] && dp[idx(len - k, i + k, j + k)]) ||
                        (dp[idx(k, i, j + len - k)] && dp[idx(len - k, i + k, j)])) {
                        dp[idx(len, i, j)] = 1;
                        break;
                    }
                }
            }
        }
    }
    return dp[idx(n, 0, 0)] === 1;
};
```

