Sort the products, then binary search for each prefix.

1. Sort `products` lexicographically. The default JS sort compares by UTF-16 code units, which is correct for lowercase letters.
2. For each prefix of `searchWord`, find the first index `i` where `products[i] >= prefix` (a lower bound).
3. Starting at `i`, take up to three consecutive products that start with the prefix. All matches for a prefix sit contiguously from that index, so the first three are the lexicographically smallest.
4. Each prefix is a substring, so building them costs O(L²) in total. With `searchWord.length <= 1000`, that is fine.

```javascript
/**
 * @param {string[]} products
 * @param {string} searchWord
 * @return {string[][]}
 */
var suggestedProducts = function(products, searchWord) {
    products.sort();
    const res = [];
    const n = products.length;
    let prefix = "";
    let start = 0;
    for (const ch of searchWord) {
        prefix += ch;
        let lo = start, hi = n;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (products[mid] < prefix) lo = mid + 1;
            else hi = mid;
        }
        start = lo;
        const cur = [];
        for (let i = lo; i < Math.min(lo + 3, n); i++) {
            if (products[i].startsWith(prefix)) cur.push(products[i]);
            else break;
        }
        res.push(cur);
    }
    return res;
};
```

