Keep the current window as a sorted array. Each step, find the outgoing element's position by binary search and remove it with `splice`. Then find the insertion point for the incoming element by binary search and insert it with `splice`.

Each step costs O(k) element shifting. With n, k up to 1e5 that is about 1e10 in the worst case on paper. `splice` is a fast memmove, though, and the worst case is near k ≈ n/2, giving n²/4 ≈ 2.5e9 shifts. That is risky.

A safer option is to compress the values and use a Fenwick tree (BIT):

1. Sort the unique values and map each number to its rank.
2. To slide the window, add 1 at the incoming element's rank and subtract 1 at the outgoing element's rank.
3. To find the m-th smallest element in the window, walk down the BIT: start with `pos = 0` and step through powers of two. Advance whenever `tree[pos + step] < m`, subtracting that count from `m`. The answer index is `pos + 1`.
4. Medians:
   - If k is odd, the median is the ((k+1)/2)-th smallest.
   - If k is even, it is the average of the (k/2)-th and (k/2 + 1)-th smallest.

Values range from about -2^31 to 2^31. Their sum fits exactly in a double, so compute `(a + b) / 2` directly.

```javascript
/**
 * @param {number[]} nums
 * @param {number} k
 * @return {number[]}
 */
var medianSlidingWindow = function(nums, k) {
    const n = nums.length;
    const sorted = Array.from(new Set(nums)).sort((a, b) => a - b);
    const m = sorted.length;
    const rank = new Map();
    for (let i = 0; i < m; i++) rank.set(sorted[i], i + 1);
    const ranks = new Int32Array(n);
    for (let i = 0; i < n; i++) ranks[i] = rank.get(nums[i]);
    const tree = new Int32Array(m + 1);
    const add = (i, v) => {
        for (; i <= m; i += i & -i) tree[i] += v;
    };
    let LOG = 1;
    while ((LOG << 1) <= m) LOG <<= 1;
    const kth = (t) => {
        let pos = 0;
        for (let step = LOG; step > 0; step >>= 1) {
            const np = pos + step;
            if (np <= m && tree[np] < t) {
                pos = np;
                t -= tree[np];
            }
        }
        return sorted[pos]; // index pos+1 in 1-based -> sorted[pos]
    };
    const res = [];
    for (let i = 0; i < n; i++) {
        add(ranks[i], 1);
        if (i >= k) add(ranks[i - k], -1);
        if (i >= k - 1) {
            if (k & 1) {
                res.push(kth((k + 1) >> 1));
            } else {
                const a = kth(k >> 1), b = kth((k >> 1) + 1);
                res.push((a + b) / 2);
            }
        }
    }
    return res;
};
