Use a greedy approach: build the string one character at a time.

At each step, decide whether to write `'a'`:
- If the last two characters are both `'a'`, we must not write `'a'`.
- If the last two characters are both `'b'`, we must write `'a'`.
- Otherwise, write the letter with the larger remaining count. Ties go to `'a'`.

If we write `'a'`, decrement `a`; otherwise write `'b'` and decrement `b`. Repeat until both counts reach zero.

```javascript
/**
 * @param {number} a
 * @param {number} b
 * @return {string}
 */
var strWithout3a3b = function(a, b) {
    const res = [];
    while (a > 0 || b > 0) {
        const n = res.length;
        let writeA;
        if (n >= 2 && res[n - 1] === res[n - 2]) {
            writeA = res[n - 1] === 'b';
        } else {
            writeA = a >= b;
        }
        if (writeA) {
            res.push('a');
            a--;
        } else {
            res.push('b');
            b--;
        }
    }
    return res.join('');
};
```

