Combine both sentences and count how often each word appears. A word is uncommon exactly when its combined count is 1: it then appears once in one sentence and not at all in the other. So we return every word whose count is 1.

```javascript
/**
 * @param {string} s1
 * @param {string} s2
 * @return {string[]}
 */
var uncommonFromSentences = function(s1, s2) {
    const count = new Map();
    for (const w of (s1 + " " + s2).split(" ")) {
        if (w.length === 0) continue;
        count.set(w, (count.get(w) || 0) + 1);
    }
    const res = [];
    for (const [w, c] of count) {
        if (c === 1) res.push(w);
    }
    return res;
};
```

