Approach:

1. **Count parents.** For every node, record how many times it appears as a child. Any node with more than one parent means the structure is not a tree, so return false.
2. **Find the root.** The root is the node with zero parents. There must be exactly one such node; zero or several means failure.
3. **Check connectivity.** Run a BFS/DFS from the root, marking visited nodes. If a node is reached twice, there is a cycle, so return false. At the end, the visited count must equal `n`.

Why this is enough: every node except the root has exactly one parent, so there are `n - 1` edges. If all `n` nodes are reachable from the root, the graph is a tree. A cycle cannot be reachable from the root, because the root has no parent and every other node has one. So the reachability count alone catches cycles, and the duplicate-visit check is just a safety guard.

```javascript
/**
 * @param {number} n
 * @param {number[]} leftChild
 * @param {number[]} rightChild
 * @return {boolean}
 */
var validateBinaryTreeNodes = function(n, leftChild, rightChild) {
    const indeg = new Int32Array(n);
    for (let i = 0; i < n; i++) {
        if (leftChild[i] !== -1) {
            if (++indeg[leftChild[i]] > 1) return false;
        }
        if (rightChild[i] !== -1) {
            if (++indeg[rightChild[i]] > 1) return false;
        }
    }
    let root = -1;
    for (let i = 0; i < n; i++) {
        if (indeg[i] === 0) {
            if (root !== -1) return false;
            root = i;
        }
    }
    if (root === -1) return false;
    const visited = new Uint8Array(n);
    const stack = [root];
    visited[root] = 1;
    let count = 0;
    while (stack.length) {
        const u = stack.pop();
        count++;
        for (const c of [leftChild[u], rightChild[u]]) {
            if (c !== -1) {
                if (visited[c]) return false;
                visited[c] = 1;
                stack.push(c);
            }
        }
    }
    return count === n;
};
